vertexShader:
varying vec2 vUv;
void main() {
vUv = uv;
gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}

fragmentShader:
uniform sampler2D u_texture;
uniform float u_time;
varying vec2 vUv;
void main() {
vec2 uv = vUv;
float glitchOffset = sin(uv.y * 50.0 + u_time * 15.0) * 0.005;
glitchOffset *= step(0.95, sin(u_time * 5.0)); 
float r = texture2D(u_texture, uv + vec2(glitchOffset, 0.0)).r;
float g = texture2D(u_texture, uv).g;
float b = texture2D(u_texture, uv - vec2(glitchOffset, 0.0)).b;
float alpha = texture2D(u_texture, uv).a;
float scanline = sin(uv.y * 800.0) * 0.04;
vec3 finalColor = vec3(r, g, b) - scanline;
gl_FragColor = vec4(finalColor, alpha);
}

vertexShader:
varying vec2 vUv;
varying vec3 vPosition;
uniform float u_time;
void main() {
vUv = uv;
vPosition = position;
float pulseAmplitude = 0.05;
float pulseFrequency = 5.0;
float pulse = sin(u_time * pulseFrequency + position.y * 2.0) * pulseAmplitude;
vec3 excitedPosition = position + (normalize(position) * pulse);
gl_Position = projectionMatrix * modelViewMatrix * vec4(excitedPosition, 1.0);
}

fragmentShader:
uniform sampler2D u_texture;
uniform float u_time;
varying vec2 vUv;
float random(vec2 st) {
return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123);
}
void main() {
vec2 uv = vUv;
vec4 texColor = texture2D(u_texture, uv);
float alpha = texColor.a;
if(alpha < 0.01) discard; 
vec3 baseRainbow = 0.5 + 0.5 * cos(u_time + uv.xyx + vec3(0, 2, 4));
float glowIntensity = pow(alpha, 3.0) * 2.0;
vec3 electricGlow = baseRainbow * glowIntensity;
float sparkNoise = random(uv * 50.0 + sin(u_time * 10.0));
float sparks = step(0.99, sparkNoise + random(uv + u_time) * 0.1);
vec3 sparkColor = vec3(1.0);
float flicker = 0.8 + 0.2 * sin(u_time * 30.0);
float finalAlpha = alpha * flicker;
vec3 finalRGB = texColor.rgb;
finalRGB += electricGlow * (0.8 + 0.2 * sin(u_time * 10.0));
finalRGB += sparkColor * sparks;
gl_FragColor = vec4(finalRGB, finalAlpha);
}

vertexShader:
varying vec2 vUv;

void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}

fragmentShader:
uniform sampler2D u_texture;
uniform float u_time;
varying vec2 vUv;

void main() {
  float gridSize = 48.0;
  vec2 pixelatedUV = floor(vUv * gridSize) / gridSize;

  vec4 tex = texture2D(u_texture, pixelatedUV);
  if(tex.a < 0.1) discard;

  float r = sin(u_time * 12.0) * 0.5 + 0.5;
  float g = sin(u_time * 15.0 + 2.0) * 0.5 + 0.5;
  float b = sin(u_time * 18.0 + 4.0) * 0.5 + 0.5;

  vec3 rainbow = vec3(r, g, b);
  vec3 finalColor = step(0.3, tex.rgb) * rainbow * 2.5;

  gl_FragColor = vec4(finalColor, tex.a);
}

vertexShader:
varying vec2 vUv;
uniform float u_time;

void main() {
  vUv = uv;

  float swayX = sin(u_time * 2.0 + position.y * 3.0) * 0.03;
  float swayY = cos(u_time * 1.5 + position.x * 2.0) * 0.03;

  vec3 pos = position;
  pos.x += swayX;
  pos.y += swayY;

  gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
}

fragmentShader:
uniform sampler2D u_texture;
uniform float u_time;
varying vec2 vUv;

float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123);
}

void main() {
  vec4 tex = texture2D(u_texture, vUv);
  if(tex.a < 0.05) discard;

  float starNoise = random(vUv * 80.0 + u_time * 0.2);
  float stars = step(0.98, starNoise + random(vUv + u_time) * 0.1); 

  vec3 spaceColor = tex.rgb * vec3(0.5, 0.0, 1.5);

  vec3 finalColor = spaceColor + vec3(stars * 2.0);

  float ghostlyAlpha = tex.a * (0.6 + 0.4 * sin(u_time * 3.0 + vUv.x * 5.0));

  gl_FragColor = vec4(finalColor, ghostlyAlpha);
}

vertexShader:
varying vec2 vUv;
uniform float u_time;

void main() {
  vUv = uv;

  float tear = sin(position.y * 20.0 + u_time * 30.0);
  float glitchActive = step(0.95, sin(u_time * 8.0));

  vec3 pos = position;
  pos.x += tear * 0.05 * glitchActive;

  gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
}

fragmentShader:
uniform sampler2D u_texture;
uniform float u_time;
varying vec2 vUv;

void main() {
  vec4 tex = texture2D(u_texture, vUv);
  if(tex.a < 0.05) discard;

  float scanline = sin(vUv.y * 150.0 - u_time * 20.0) * 0.5 + 0.5;

  vec3 holoColor = vec3(0.1, 1.5, 1.0) * tex.rgb;

  vec3 finalColor = holoColor * (0.4 + 0.6 * scanline);

  gl_FragColor = vec4(finalColor, tex.a * (0.7 + 0.3 * scanline));
}
